type ReadToken = (token: string) => { sub: number; exp: number } | undefined;

function requireUserId(headers: Record<string, string | undefined>, readToken: ReadToken): number {
  const header = headers["authorization"];
  const token = typeof header === "string" && header.startsWith("Bearer ") ? header.slice(7) : undefined;
  const payload = token === undefined ? undefined : readToken(token);
  if (payload === undefined) throw new HttpError(401, "unauthorized");
  return payload.sub;
}

