function parseStored(stored: string): { salt: string; key: string } | undefined {
  const parts = stored.split("$");
  if (parts.length !== 3) return undefined;
  const [scheme, salt, key] = parts;
  if (scheme !== "scrypt" || !salt || !key) return undefined;
  return { salt, key };
}

